Library IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_Unsigned.all;Library Synopsys;use Synopsys.attributes.all;entity Prob_8_26_vhdl is		port (Product: out Std_Logic_vector (9 downto 0); Ready: out Std_Logic; 			Multiplicand, Multiplier: out Std_Logic_vector (4 downto 0); Start, clock, reset_b: in Std_Logic);end Prob_8_26_vhdl;	architecture Behavioral of Prob_8_26_vhdl is-- Default configuration: 5-bit datapath	constant	dp_width: integer := 5; 		--Set to width of datapath	constant	BC_size: integer 	:= 3;		-- Size of bit counter	type State_type is (S_idle, S_add_shift);	attribute enum_encoding of State_type: type is "01 10";	signal state, next_state: State_type;	signal A, B, Q: Std_Logic_vector (dp_width-1 downto 0);				-- Sized for datapath  	signal 	C: Std_Logic;  	signal	P: integer;	signal 	Load_regs, Decr_P, Add_shift, Shift: Std_Logic;	signal 	Sum: Std_logic_vector (dp_width downto 0);begin				Product <= C & A & Q;	Sum <= A + B;  	Zero <= '1' when P = 0 else '0';				--  Counter is zero	Ready <= '1' when state = S_idle else '0';	-- Controller status	-- Datapath unit RTL (Included asynch, active-low reset)	process (clock, reset_b) begin		if (reset_b = '0') then			P <= dp_width;			C <= '0';			for k in 0 to dp_width-1 loop					B(k) <= '0'; A(k) <= '0'; Q(k) <= '0';			end loop; 		elsif clock'event and clock = '1' then 			case (Load_regs & Decr_P & Add_shift & Shift) is			when "1000" =>				--if Load_regs = '1' then      		C <= '0';    		      		P <= dp_width;								for k in dp_width-1 downto 0 loop 					A(k) <= '0';  				end loop;      		B <= Multiplicand;     			Q <= Multiplier;							when "0100" =>			--elsif (Decr_P = '1') then 				P <= P -1;							when "0010" =>			--elsif (Add_shift = '1') then 				Q <= Sum(0) & Q(dp_width -1 downto 1);				A <= C & Sum(dp_width-1 downto 1);				C <= Sum(dp_width);							when "0001" =>			--elsif Shift = '1' then 				Q <= A(0) & Q(dp_width -1 downto 1);				A <= C & A(dp_width-1 downto 1);				C <= '0';				end case;		end if;	end process;  -- Control unit RTL  	process  (clock, reset_b) begin		if (reset_b = '0') then state <= S_idle; 		elsif clock'event and clock = '1' then state <= next_state; 		end if;	end process;	  	process  (state, Start, Q(0), Zero) begin    		next_state <= S_idle;    		Load_regs <= '0';    		Decr_P <= '0';    		Add_shift <= '0';    		Shift <= '0';			case (state) is      			when S_idle =>	if (Start = '1') then 											next_state <= S_add_shift; 											Load_regs <= '1'; 										end if;															when S_add_shift =>	Decr_P <= '1';											 	if Zero = '1' then next_state <= S_idle;												else next_state <= S_add_shift; 												end if; 																									if Q(0) = '1' then 													Add_shift <= '1'; 													Shift <= '1'; 												end if;	  																																				      					when others => next_state <= S_idle;			end case;    end process;end Behavioral;